def test_task_1_appends_complete_tool_turns():
    messages = initial_messages("task", "system")
    updated = append_tool_result(messages, '{"tool":"list_files"}', "file a.py")

    assert updated[-2:] == [
        {"role": "assistant", "content": '{"tool":"list_files"}'},
        {"role": "user", "content": "Tool result:\nfile a.py"},
    ]
    assert messages == initial_messages("task", "system")


def test_task_2_compaction_keeps_anchors_and_newest_complete_turn():
    messages = initial_messages("task", "system")
    messages = append_tool_result(messages, "old action" * 10, "old result" * 10)
    messages = append_tool_result(messages, "new action", "new result")

    compacted = compact_messages(messages, 50)

    assert compacted[:2] == messages[:2]
    assert compacted[-2:] == messages[-2:]
    assert len(compacted) == 4


def test_task_3_session_events_round_trip_and_persist(tmp_path):
    store = SessionStore(tmp_path, "test-model")
    session = store.create("1" * 32)
    event = session.append("user_message", content="inspect the project", kind="task")

    loaded = store.load(session.session_id)

    assert SessionEvent.from_dict(event.to_dict()) == event
    assert loaded.events[-1] == event
    assert loaded.messages("system")[-1] == {
        "role": "user",
        "content": "inspect the project",
    }
    assert session.path is not None
    assert session.path.stat().st_mode & 0o077 == 0


def test_task_3_event_views_cannot_mutate_the_durable_replay(tmp_path):
    session = memory_session(tmp_path, "test-model")
    event = session.append("user_message", content="original", nested={"value": "kept"})
    event.data["content"] = "mutated"
    event.to_dict()["data"]["nested"]["value"] = "mutated"
    session.events[-1].data["nested"]["value"] = "mutated"

    assert session.messages("system")[-1]["content"] == "original"
    assert session.events[-1].data["nested"]["value"] == "kept"


