def test_task_3_resume_rejects_workspace_and_model_mismatch(tmp_path):
    workspace = tmp_path / "workspace"
    other = tmp_path / "other"
    workspace.mkdir()
    other.mkdir()
    session = SessionStore(workspace, "model-a").create("2" * 32)
    other_sessions = other / ".tiny-llm" / "sessions"
    other_sessions.mkdir(parents=True)
    assert session.path is not None
    copied = other_sessions / session.path.name
    copied.write_bytes(session.path.read_bytes())
    copied.chmod(0o600)

    with pytest.raises(ValueError, match="different workspace"):
        SessionStore(other, "model-a").load(session.session_id)
    with pytest.raises(ValueError, match="different model"):
        SessionStore(workspace, "model-b").load(session.session_id)

    mismatched_session = memory_session(workspace, "model-a")
    mismatched_session.append("user_message", content="task", kind="task")
    with pytest.raises(ValueError, match="different workspace"):
        run_agent(
            None,
            lambda _messages: '{"final":"must not run"}',
            Workspace(ToolPolicy(other)),
            session=mismatched_session,
        )

    with pytest.raises(ValueError, match="does not exist"):
        SessionStore(workspace, "model-a").load("1" * 32)


